package dev.raf.radar;
import android.content.Context;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;
public class DiagnosticsTest {
 @Test public void uploadFailureSurvivesRestartAndRetriesWithEncryptedSession()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Fixture")).put("session",new String(new char[64]).replace('\0','a')));Diagnostics.Upload original=Diagnostics.transport;DiagnosticJournal originalJournal=Diagnostics.journal;AtomicInteger calls=new AtomicInteger();
 try{Diagnostics.worker.submit(()->{try{File dir=new File(c.getCacheDir(),"diagnostic-test-"+System.nanoTime());Diagnostics.journal=new DiagnosticJournal(dir,System::currentTimeMillis);Diagnostics.transport=(body,token)->{assertEquals(64,token.length());assertFalse(body.contains("Fixture"));calls.incrementAndGet();throw new IOException("offline secret");};Diagnostics.retryAt=0;Diagnostics.journal.event("taxi","timeout","error",new IOException("cookie secret"),0,-1,-1,null);Diagnostics.journal.report("timeout",Diagnostics.device(),Diagnostics.snapshot(),true);Diagnostics.flush();assertEquals(1,calls.get());assertNotNull(Diagnostics.journal.pending());Diagnostics.journal=new DiagnosticJournal(dir,System::currentTimeMillis);Diagnostics.transport=(body,token)->200;Diagnostics.retryAt=0;Diagnostics.flush();assertNull(Diagnostics.journal.pending());assertTrue(s.prefs.getLong("diagUploadedAt",0)>0);}catch(Exception e){throw new RuntimeException(e);}}).get(15,TimeUnit.SECONDS);}finally{Diagnostics.worker.submit(()->{Diagnostics.transport=original;Diagnostics.journal=originalJournal;Diagnostics.retryAt=0;AccountClient.clear(s);}).get(5,TimeUnit.SECONDS);}}
 @Test public void watchdogReportsExpectedButStoppedService()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().putBoolean("diagMonitorExpected",true).commit();Diagnostics.check();Diagnostics.worker.submit(()->{}).get(10,TimeUnit.SECONDS);assertTrue(s.prefs.getString("diagLastError","").contains("service_inactive"));s.prefs.edit().putBoolean("diagMonitorExpected",false).commit();}
}
